function validate(input) {
  for (const value of input) {
    if (value === undefined) return 'o1 and o2 must be JSON values.';
    if (JSON.stringify(value).length > 100000) return 'Keep each value under 100,000 characters of JSON.';
    // An array or object is one level deep, plus the depth of its deepest member.
    const stack = [[value, 1]];
    while (stack.length) {
      const [item, depth] = stack.pop();
      if (item === null || typeof item !== 'object') continue;
      if (depth > 10) return 'Keep o1 and o2 at most 10 levels deep.';
      for (const child of Object.values(item)) stack.push([child, depth + 1]);
    }
  }
  return null;
}

