function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const names = ['x', 'y', 'z', 'L', 'id', 'name', 'a', 'b'];
  let budget = small ? 12 : 4000;
  const primitive = () => {
    const roll = rand();
    if (roll < 0.4) return Math.floor(rand() * 7) - 3;
    if (roll < 0.7) return pick(['', 'a', 'b', '1', '0', 'null']);
    if (roll < 0.85) return rand() < 0.5;
    return null;
  };
  // A random value with at most 3 (small) or 8 (large) levels of nesting.
  const value = (depth) => {
    budget--;
    const stop = depth === 0 ? (small ? 0.1 : 0) : small ? 0.45 : 0.6;
    if (depth >= (small ? 3 : 8) || budget <= 0 || rand() < stop) return primitive();
    const length = depth === 0 && !small ? 150 : Math.floor(rand() * (small ? 4 : 8));
    if (rand() < 0.5) return Array.from({ length }, () => value(depth + 1));
    const object = {};
    for (let i = 0; i < length; i++) object[pick(names) + (small ? '' : Math.floor(rand() * 20))] = value(depth + 1);
    return object;
  };
  // A deep copy whose objects list their keys in a shuffled order.
  const copy = (item) => {
    if (Array.isArray(item)) return item.map(copy);
    if (item === null || typeof item !== 'object') return item;
    const keys = Object.keys(item), out = {};
    for (let i = keys.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [keys[i], keys[j]] = [keys[j], keys[i]]; }
    for (const key of keys) out[key] = copy(item[key]);
    return out;
  };
  // A small change to one value, usually one that breaks deep equality.
  const changed = (old) => {
    const roll = rand();
    if (Array.isArray(old)) {
      if (roll < 0.4) return Object.assign({}, old);
      if (roll < 0.7 || old.length < 2) return [...old, primitive()];
      return [...old].reverse();
    }
    if (old !== null && typeof old === 'object') {
      const keys = Object.keys(old), out = Object.assign({}, old);
      if (keys.length && roll < 0.4) { delete out[pick(keys)]; return out; }
      if (roll < 0.7) { out.extra = primitive(); return out; }
      return Object.values(old);
    }
    if (typeof old === 'number') return roll < 0.6 ? String(old) : old + 1;
    if (typeof old === 'string') return old !== '' && roll < 0.5 && String(Number(old)) === old ? Number(old) : old + 'x';
    if (typeof old === 'boolean') return roll < 0.5 ? !old : Number(old);
    return pick([{}, [], 0, false, 'null']);
  };
  const o1 = value(0);
  let o2 = copy(o1);
  // Half of the pairs get one change somewhere, often deep inside.
  if (rand() < 0.5) {
    const slots = [];
    const walk = (item) => { if (item !== null && typeof item === 'object') for (const key of Object.keys(item)) { slots.push([item, key]); walk(item[key]); } };
    walk(o2);
    if (slots.length && rand() < 0.85) { const [parent, key] = pick(slots); parent[key] = changed(parent[key]); }
    else o2 = changed(o2);
  }
  return rand() < 0.5 ? [o1, o2] : [o2, o1];
}
